using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedChestBattleCustomEventSetup", menuName = "Data/BattleSceneSetups/CorruptedChestBattleCustomEventSetup", order = 0)]
public class CorruptedChestBattleCustomEventSetup : CustomEventSetup
{
	[Header("Meissa Battle Handler")]
	[SerializeField]
	private GameObject corruptedChestBattleHandler;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private ClearingReward corruptedChestClearingReward;

	public override void SetupScene()
	{
		mapHandler.SetClearingReward(corruptedChestClearingReward, goToEndOfBattleState: false);
		mapHandler.ResetCurrentRewardCounter();
		base.SetupScene();
		Object.Instantiate(corruptedChestBattleHandler);
	}
}
